<!--大模型助手悬浮球  -->
<template>
  <div class="floating-ball" :style="{ bottom: ballBottom + 'px' }" @click="toggleChat">
    <div
      class="ball-stage"
      :class="{ 'is-thinking': isThinking, 'is-flash': flashing }"
      @mouseenter="hovering = true"
      @mouseleave="hovering = false">
      <!-- 圈内转圈：高光角度旋转 -->
      <span class="ball-aura" aria-hidden="true"></span>
      <!-- 最外围边缘：表情切换时闪一下的光圈 -->
      <span class="ball-flash" aria-hidden="true"></span>
      <!-- 绿色大模型小球图标 -->
      <svg class="ball-face" viewBox="0 0 120 120" xmlns="http://www.w3.org/2000/svg">
        <defs>
          <linearGradient id="ballFaceGradient" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stop-color="#b6f4d7"/>
            <stop offset="55%" stop-color="#a9efcc"/>
            <stop offset="100%" stop-color="#9deac4"/>
          </linearGradient>
        </defs>
        <!-- 耳朵：白色饱满椭圆 -->
        <ellipse cx="19" cy="68" rx="12" ry="13" fill="#ffffff"/>
        <ellipse cx="103" cy="68" rx="12" ry="13" fill="#ffffff"/>
        <!-- 头部：圆润馒头形，顶部三个圆润山丘（中间最高、等宽） -->
        <path
          d="M 60 107 C 44 107 22 98 22 80 C 22 67 23.5 55 27 47 C 28.5 40 30 34 33 31 C 36 28.5 37.5 28 40 28 C 42.5 28 44 29.5 45 31.5 C 46 34 46.5 38 47.5 43 C 48.5 45 49 45.5 49 45.5 C 50.5 45.5 51.5 39 53 33 C 54.5 27 55 17 60 17 C 65 17 65.5 27 67 33 C 68.5 39 69.5 45.5 71 45.5 C 71 45.5 71.5 45 72.5 43 C 73.5 38 74 34 75 31.5 C 76 29.5 77.5 28 80 28 C 82.5 28 84 28.5 87 31 C 90 34 91.5 40 93 47 C 96.5 55 98 67 98 80 C 98 98 76 107 60 107 Z"
          fill="url(#ballFaceGradient)"
          stroke="#ffffff"
          stroke-width="5"
          stroke-linejoin="round"
          stroke-linecap="round"/>
        <!-- 发呆：两个对称白色竖长圆角矩形 -->
        <g class="eyes eyes-idle" fill="#ffffff">
          <rect x="42" y="56" width="6.5" height="18" rx="3.25"/>
          <rect x="61.5" y="56" width="6.5" height="18" rx="3.25"/>
        </g>
        <!-- 眯眼：两个对称白色横条 -->
        <g class="eyes eyes-thinking" fill="#ffffff">
          <rect x="46" y="66" width="11" height="7.5" rx="2.75"/>
          <rect x="66" y="66" width="11" height="7.5" rx="2.75"/>
        </g>
      </svg>
    </div>
    <!-- 一些悬浮的提示词 -->
    <transition name="ball-fade">
      <div v-if="tipVisible" class="floating-ball-tip">
        {{ currentTip }}
      </div>
    </transition>
    <!-- 点击出现小型聊天窗口 -->
    <chat-window
      :visible="chatWindowVisible"
      :show-below="shouldShowBelow"
      @thinking="onThinking"
      @update-visible="updateChatWindowVisible" />
  </div>
</template>

<script>
import ChatWindow from './ChatWindow.vue'

export default {
  name: 'FloatingBall',
  components: {
    ChatWindow
  },
  data () {
    return {
      tipVisible: false,
      currentTip: '',
      tipTimer: null,
      hideTimer: null,
      ballBottom: 176,
      targetBottom: 176,
      lastScrollY: 0,
      scrollDirection: 'down',
      animationFrame: null,
      chatWindowVisible: false,
      // 表情 / 动效状态
      hovering: false,
      answerThinking: false,
      randomSpinning: false,
      flashing: false,
      flashTimer: null,
      randomIdleTimer: null,
      randomSpinTimer: null
    }
  },
  computed: {
    shouldShowBelow () {
      // 浮动球靠近顶部（bottom 值较大）时，聊天窗口显示在球下方；否则显示在上方
      return this.ballBottom > window.innerHeight - 360
    },
    // 转圈（横眼表情）：悬停 / 回答中 / 随机发呆转圈
    isThinking () {
      return this.hovering || this.answerThinking || this.randomSpinning
    }
  },
  watch: {
    // 表情切换时闪一下光圈
    isThinking () {
      this.triggerFlash()
    }
  },
  mounted () {
    this.showTip()
    this.tipTimer = setInterval(this.showTip, 15000)
    this.lastScrollY = window.scrollY || window.pageYOffset
    this.ballBottom = 176
    this.targetBottom = 176
    window.addEventListener('scroll', this.handleScroll, { passive: true })
    this.animatePosition()
    this.scheduleRandomSpin()
  },
  beforeDestroy () {
    if (this.tipTimer) {
      clearInterval(this.tipTimer)
    }
    if (this.hideTimer) {
      clearTimeout(this.hideTimer)
    }
    if (this.flashTimer) {
      clearTimeout(this.flashTimer)
    }
    if (this.randomIdleTimer) {
      clearTimeout(this.randomIdleTimer)
    }
    if (this.randomSpinTimer) {
      clearTimeout(this.randomSpinTimer)
    }
    if (this.animationFrame) {
      cancelAnimationFrame(this.animationFrame)
    }
    window.removeEventListener('scroll', this.handleScroll)
  },
  methods: {
    // 检查登录状态
    async checkLoginStatus () {
      try {
        const resp = await this.$axios.get('/currentUser')
        if (resp && resp.data.code === 200) {
          return true
        } else {
          return false
        }
      } catch (error) {
        return false
      }
    },
    async toggleChat () {
      // 检查登录状态
      const isLoggedIn = await this.checkLoginStatus()
      if (!isLoggedIn) {
        this.$message.warning('请先登录后再使用大模型助手')
        this.$router.push({
          path: '/login',
          query: { redirect: this.$route.fullPath }
        })
        return
      }
      this.chatWindowVisible = !this.chatWindowVisible
    },
    updateChatWindowVisible (visible) {
      this.chatWindowVisible = visible
    },
    // 大模型回答中：由聊天窗口通知
    onThinking (val) {
      this.answerThinking = val
    },
    // 闪一下光圈
    triggerFlash () {
      if (this.flashTimer) {
        clearTimeout(this.flashTimer)
      }
      this.flashing = false
      this.$nextTick(() => {
        this.flashing = true
        this.flashTimer = setTimeout(() => {
          this.flashing = false
        }, 780)
      })
    },
    // 随机发呆：隔一段时间随机转一会儿圈
    scheduleRandomSpin () {
      if (this.randomIdleTimer) {
        clearTimeout(this.randomIdleTimer)
      }
      this.randomIdleTimer = setTimeout(() => {
        this.randomSpinning = true
        this.randomSpinTimer = setTimeout(() => {
          this.randomSpinning = false
          this.scheduleRandomSpin()
        }, 1600 + Math.random() * 2000)
      }, 5000 + Math.random() * 9000)
    },
    handleScroll () {
      this.updateBallPosition()
      if (!this.animationFrame) {
        this.animatePosition()
      }
    },
    updateBallPosition () {
      const currentScrollY = window.scrollY || window.pageYOffset
      const scrollDelta = currentScrollY - this.lastScrollY
      const viewportHeight = window.innerHeight

      if (scrollDelta > 5) {
        this.scrollDirection = 'down'
        this.targetBottom = 176
      } else if (scrollDelta < -5) {
        this.scrollDirection = 'up'
        this.targetBottom = viewportHeight - 176
      }

      this.lastScrollY = currentScrollY
    },
    animatePosition () {
      const diff = this.targetBottom - this.ballBottom
      if (Math.abs(diff) > 0.5) {
        this.ballBottom += diff * 0.06
        this.animationFrame = requestAnimationFrame(() => {
          this.animatePosition()
        })
      } else {
        this.ballBottom = this.targetBottom
        this.animationFrame = null
      }
    },
    getTimeBasedTips () {
      const hour = new Date().getHours()

      const commonTips = [
        '要不要让我告诉你最近有哪些值得参加的比赛吗？',
        '需要我帮你找一些有用的竞赛准备资料吗？',
        '要不要我帮你分析一下哪些竞赛适合你？',
        '需要我帮你整理一下竞赛时间表吗？',
        '要不要我帮你找一些编程竞赛的题目？',
        '需要我帮你了解数学建模竞赛的流程吗？',
        '要不要我帮你找一些竞赛的获奖经验分享？',
        '需要我帮你分析一下如何选择竞赛项目吗？',
        '要不要我帮你找一些竞赛的组队信息？',
        '需要我帮你制定竞赛准备计划吗？',
        '要不要我帮你了解各类竞赛的报名要求？',
        '需要我帮你找一些竞赛的真题和解析吗？',
        '要不要我帮你分析一下竞赛的评分标准？',
        '你知道吗？数学建模竞赛通常需要3人组队，考察建模、编程和论文写作能力',
        'ACM程序设计竞赛是个人或团队参加的算法竞赛，需要扎实的编程基础',
        '全国大学生数学竞赛分为数学专业组和非数学专业组，考察数学基础',
        '互联网+大学生创新创业大赛注重创新性和商业价值，适合有创业想法的同学',
        '挑战杯是全国大学生课外学术科技作品竞赛，涵盖多个学科领域',
        '蓝桥杯是面向大学生的IT类竞赛，包括软件、硬件和设计等多个方向',
        '全国大学生电子设计竞赛需要团队合作，考察电子系统设计能力',
        '中国大学生计算机设计大赛涵盖多个计算机相关领域，适合不同专业的同学',
        '全国大学生英语竞赛分为A、B、C、D四个类别，适合不同英语水平的同学',
        '全国大学生物理实验竞赛注重实验设计和操作能力，需要团队协作',
        '全国大学生化学实验邀请赛考察化学实验技能和理论知识',
        '全国大学生机械创新设计大赛需要创新思维和机械设计能力',
        '全国大学生结构设计竞赛考察结构设计和模型制作能力',
        '全国大学生广告艺术大赛适合有创意和设计能力的同学',
        '有什么竞赛相关的问题随时可以问我哦',
        '遇到困难不要怕，我们一起解决',
        '保持好心情，竞赛路上我陪你一起进步',
        '记得劳逸结合，效率更高哦',
        '有什么想法可以和我分享，我随时准备为你答疑解惑'
      ]

      if (hour >= 6 && hour < 11) {
        const morningTips = [
          '早上好，新的一天开始了！',
          '早上好，今天有什么竞赛计划吗？',
          '早上好，吃早餐了吗？记得补充能量哦~',
          '早上好，要不要让我帮你看看今天的竞赛安排？'
        ]
        return [...morningTips, ...commonTips]
      } else if (hour >= 11 && hour < 14) {
        const noonTips = [
          '中午好，记得好好吃饭哦~',
          '中午好，午饭吃了什么好吃的？',
          '中午好，要不要休息一下？',
          '中午好，需要我帮你整理下午的竞赛计划吗？'
        ]
        return [...noonTips, ...commonTips]
      } else if (hour >= 14 && hour < 18) {
        const afternoonTips = [
          '下午好，学习/工作还顺利吗？',
          '下午好，今天的任务完成得怎么样？',
          '下午好，需要我帮你查点什么吗？',
          '下午好，要不要我帮你分析一下竞赛准备进度？'
        ]
        return [...afternoonTips, ...commonTips]
      } else if (hour >= 18 && hour < 23) {
        const eveningTips = [
          '晚上好，今天过得怎么样？',
          '晚上好，该适当放松一下啦~',
          '晚上好，要不要我帮你规划明天的竞赛安排？'
        ]
        return [...eveningTips, ...commonTips]
      } else {
        const nightTips = [
          '这么晚还在学习，要注意休息哦',
          '这么晚还没休息？要注意身体哦',
          '夜深了，有困惑的话可以来和我聊聊',
          '这么晚还在努力，记得早点休息哦'
        ]
        return [...nightTips, ...commonTips]
      }
    },
    showTip () {
      const tips = this.getTimeBasedTips()
      const index = Math.floor(Math.random() * tips.length)
      this.currentTip = tips[index]
      this.tipVisible = true
      if (this.hideTimer) {
        clearTimeout(this.hideTimer)
      }
      this.hideTimer = setTimeout(() => {
        this.tipVisible = false
      }, 5000)
    }
  }
}
</script>

<style scoped>
.floating-ball {
  position: fixed;
  right: 60px;
  z-index: 1001;
  cursor: pointer;
  will-change: bottom;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.ball-stage {
  position: relative;
  width: 60px;
  height: 60px;
  border-radius: 50%;
  background: radial-gradient(circle at 50% 42%, #ffffff 0%, #e9f6ff 38%, #c9e8ff 74%, #ddf1ff 100%);
  box-shadow: 0 8px 22px rgba(94, 176, 232, 0.35);
  display: flex;
  align-items: center;
  justify-content: center;
  animation: floatY 3s ease-in-out infinite;
  transition: box-shadow 0.3s ease;
}

.ball-stage:hover {
  box-shadow: 0 10px 26px rgba(94, 176, 232, 0.45);
}

/* 圈内转圈：白色高光绕圈旋转 */
.ball-aura {
  position: absolute;
  inset: 3px;
  border-radius: 50%;
  background: conic-gradient(
    from 0deg,
    rgba(255, 255, 255, 0) 0deg,
    rgba(255, 255, 255, 0.12) 35deg,
    rgba(255, 255, 255, 0.9) 90deg,
    rgba(255, 255, 255, 0.12) 145deg,
    rgba(255, 255, 255, 0) 180deg,
    rgba(255, 255, 255, 0) 360deg
  );
  filter: blur(1.5px);
  opacity: 0;
  transition: opacity 0.3s ease;
  pointer-events: none;
  z-index: 0;
}

.is-thinking .ball-aura {
  opacity: 1;
  animation: ballSpin 1.4s linear infinite;
}

/* 最外围边缘：表情切换时闪一下的光圈（不旋转） */
.ball-flash {
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0);
  pointer-events: none;
  opacity: 0;
  z-index: 2;
}

.is-flash .ball-flash {
  animation: ringFlash 0.62s ease-out;
}

/* 表情 */
.ball-face {
  position: relative;
  z-index: 1;
  width: 82%;
  height: 82%;
}

.eyes {
  transform-box: fill-box;
  transform-origin: center;
  transition: opacity 0.22s ease, transform 0.22s ease;
}

.eyes-idle {
  opacity: 1;
  transform: scale(1);
}

.eyes-thinking {
  opacity: 0;
  transform: scale(0.6);
}

.is-thinking .eyes-idle {
  opacity: 0;
  transform: scale(0.6);
}

.is-thinking .eyes-thinking {
  opacity: 1;
  transform: scale(1);
}

.floating-ball-tip {
  position: absolute;
  right: 75px;
  top: 50%;
  transform: translateY(-50%);
  display: inline-block;
  min-width: 150px;
  max-width: 260px;
  padding: 10px 14px;
  border-radius: 16px;
  background: #ffffff;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);
  font-size: 13px;
  font-weight: 600;
  color: #555;
  line-height: 1.5;
  text-align: left;
  white-space: normal;
  word-break: break-word;
}

.ball-fade-enter-active,
.ball-fade-leave-active {
  transition: opacity 0.3s, transform 0.3s;
}

.ball-fade-enter {
  opacity: 0;
  transform: translateY(-50%) translateX(10px);
}

.ball-fade-leave-to {
  opacity: 0;
  transform: translateY(-50%) translateX(10px);
}

@keyframes floatY {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-10px);
  }
}

@keyframes ballSpin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@keyframes ringFlash {
  0% {
    opacity: 0;
    border-color: rgba(255, 255, 255, 0);
    transform: scale(0.94);
    box-shadow: 0 0 0 rgba(190, 238, 255, 0);
  }
  35% {
    opacity: 0.95;
    border-color: rgba(255, 255, 255, 0.95);
    transform: scale(1);
    box-shadow: 0 0 14px rgba(190, 238, 255, 0.85);
  }
  100% {
    opacity: 0;
    border-color: rgba(255, 255, 255, 0);
    transform: scale(1.08);
    box-shadow: 0 0 22px rgba(190, 238, 255, 0);
  }
}

@media (max-width: 640px) {
  .floating-ball {
    right: 12px;
  }

  .ball-stage {
    width: 56px;
    height: 56px;
  }

  .floating-ball-tip {
    top: auto;
    right: 0;
    bottom: 72px;
    min-width: 0;
    max-width: 180px;
    transform: none;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
}
</style>



